// Leak: if getSomething() throws, this connection is never returned
public Widget getSomethingBroken() throws SQLException {
    Connection conn = dataSource.getConnection();
    ResultSet rs = conn.createStatement().executeQuery("SELECT ...");
    return mapWidget(rs);
    // conn.close() never runs on the exception path
}

// Fixed: try-with-resources always returns the connection
public Widget getSomethingFixed() throws SQLException {
    try (Connection conn = dataSource.getConnection();
         Statement stmt = conn.createStatement();
         ResultSet rs = stmt.executeQuery("SELECT ...")) {
        return mapWidget(rs);
    }
}

